<script lang="ts">
 import {onDestroy} from 'svelte';import {collection,query,where,orderBy,limit,onSnapshot} from 'firebase/firestore';import {db} from '$lib/firebase';import {fromDoc} from '$lib/api/firestore';import type {ActivityEntry} from '$lib/rules/tablePlay';
 export let campaignId:string;export let isDM=false;let rows:ActivityEntry[]=[];let error='';let unsubscribe:()=>void;let current='';
 $: if(`${campaignId}:${isDM}`!==current){current=`${campaignId}:${isDM}`;unsubscribe?.();const constraints=[where('campaignId','==',campaignId),...(!isDM?[where('visibility','==','public')]:[]),orderBy('createdAt','desc'),limit(100)];unsubscribe=onSnapshot(query(collection(db,'campaign_activity'),...constraints),snapshot=>{rows=snapshot.docs.map(d=>fromDoc<ActivityEntry>(d));error='';},cause=>error=cause.message);}
 const date=(value:string)=>{const d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleString('es-AR',{dateStyle:'short',timeStyle:'short'}):'Sincronizando…';};onDestroy(()=>unsubscribe?.());
</script>
<section class="card-parchment p-3 space-y-2 text-neutral"><h3 class="font-medieval font-bold">Bitácora</h3><p class="text-xs">Últimos 100 movimientos registrados. Las entradas privadas solo las ve el DM.</p>{#if error}<p role="alert" class="text-error text-sm">{error}</p>{/if}{#if !rows.length}<p class="text-sm">Todavía no hay movimientos registrados.</p>{/if}<div class="max-h-96 overflow-y-auto">{#each rows as row}<article class="border-t border-primary/20 py-2"><p class="text-sm break-words">{row.message}</p><p class="text-xs opacity-70">{row.actorName} · {date(row.createdAt)}{row.visibility==='dm'?' · Privado del DM':''}</p></article>{/each}</div></section>
